mapper.select:
SELECT COALESCE(SUM(amount - settled_amount), 0)
FROM fin_receivable
WHERE customer_id = #{customerId}

SELECT d.material_id AS refId, m.code AS refCode, m.name AS refName, COALESCE(SUM(d.amount), 0) AS salesAmount, COALESCE(SUM(d.qty), 0) AS salesQty FROM sal_outstock o JOIN sal_outstock_detail d ON d.out_id = o.id AND d.deleted = 0 LEFT JOIN base_material m ON m.id = d.material_id WHERE o.deleted = 0 AND o.status = 10
AND o.out_date BETWEEN #{from} AND #{to}
GROUP BY d.material_id, m.code, m.name ORDER BY salesAmount DESC LIMIT 10

SELECT o.customer_id AS refId, c.code AS refCode, c.name AS refName, COALESCE(SUM(d.amount), 0) AS salesAmount, COALESCE(SUM(d.qty), 0) AS salesQty FROM sal_outstock o JOIN sal_outstock_detail d ON d.out_id = o.id AND d.deleted = 0 LEFT JOIN base_customer c ON c.id = o.customer_id WHERE o.deleted = 0 AND o.status = 10
AND o.out_date BETWEEN #{from} AND #{to}
GROUP BY o.customer_id, c.code, c.name ORDER BY salesAmount DESC LIMIT 10
